def car_race_collision(n: int) -> int:
    """
    Calculates the number of collisions in a perfectly straight line.
    The cars are driving left to right, and the two sets of cars start out
    being very far from each other.  All cars move in the same speed.
    Two cars are said to collide when a car that's moving left to right hits a car
    that's moving right to left. However, the cars are infinitely sturdy and strong.
    As a result, they continue moving in their trajectory as if they did not collide.

    This function outputs the number of such collisions.
    """
    collisions = 0
    for i in range(n):
        if i % 2 == 1:
            if i == 0:
                collisions += 1
            else:
                return 0
        else:
            if i == n - 1:
                collisions += 1
            else:
                return 0
    return collisions

