def minPath(grid, k):
    n = len(grid)
    if n == 0:
        return []

    import heapq

    start_row, start_col = 0, 0
    for r in range(n):
        for c in range(n):
            if grid[r][c] == 1:
                start_row, start_col = r, c
                break

    distances = {}
    for r in range(n):
        for c in range(n):
            distances[(r, c)] = float('inf')
    distances[(start_row, start_col)] = 0

    pq = [(0, start_row, start_col)]

    while pq:
        dist, row, col = heapq.heappop(pq)

        if dist > distances[(row, col)]:
            continue

        if row == n - 1 and col == n - 1:
            break

        for dr, dc in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
            new_row, new_col = row + dr, col + dc
            if 0 <= new_row < n and 0 <= new_col < n:
                new_dist = dist + 1
                if new_dist < distances[(new_row, new_col)]:
                    distances[(new_row, new_col)] = new_dist
                    heapq.heappush(pq, (new_dist, new_row, new_col))

    path = []
    current_row, current_col = start_row, start_col
    while current_row != 0 or current_col != 0:
        path.append(grid[current_row][current_col])

        if current_row == 0 and current_col == 0:
            break

        if current_row == 0:
            current_row += 1
        elif current_col == 0:
            current_col += 1
        else:
            current_row -= 1
            current_col -= 1

    return path[::-1]
