def exchange(lst1, lst2):
    """In this problem, you will implement a function that takes two lists of numbers,
    and determines whether it is possible to perform an exchange of elements
    between them to make lst1 a list of only even numbers.
    There is no limit on the number of exchanged elements between lst1 and lst2.
    If it is possible to exchange elements between the lst1 and lst2 to make
    all the elements of lst1 to be even, return "YES".
    Otherwise, return "NO".
    For example:
    exchange([1, 2, 3, 4], [1, 2, 3, 4]) => "YES"
    exchange([1, 2, 3, 4], [1, 5, 3, 4]) => "NO"
    It is assumed that the input lists will be non-empty.
    """
    # Input validation
    if not isinstance(lst1, list) or not isinstance(lst2, list):
        raise TypeError("Both lst1 and lst2 must be lists.")
    for item in lst1:
        if not isinstance(item, int):
            raise TypeError("All elements in lst1 must be integers.")
    for item in lst2:
        if not isinstance(item, int):
            raise TypeError("All elements in lst2 must be integers.")
    if not lst1 or not lst2:
        raise ValueError("Both lst1 and lst2 must be non-empty.")

    for num in lst1:
        if num % 2 != 0:
            found_even = False
            for num2 in lst2:
                if num2 % 2 == 0:
                    # Swap the numbers
                    lst1[lst1.index(num)] = num2
                    lst2.remove(num2)
                    found_even = True
                    break
            if not found_even:
                return "NO"
    return "YES"

