from typing import List


def parse_music(music_string: str) -> List[int]:
    """
    Parses a string representing musical notes in a special ASCII format and
    returns a list of integers corresponding to how many beats each note lasts.

    'o' - whole note, lasts four beats
    'o|' - half note, lasts two beats
    '.|' - quarter note, lasts one beat
    """

    def tokenize(music_string: str) -> List[str]:
        """Splits the music string into a list of tokens."""
        return music_string.split()

    def interpret_token(token: str) -> int:
        """Interprets a single note token and returns its beat duration."""
        if token == 'o':
            return 4
        elif token == 'o|':
            return 2
        elif token == '.|':
            return 1
        else:
            raise ValueError(f"Invalid note token: {token}")  # Handle invalid tokens

    tokens = tokenize(music_string)
    beat_durations = []
    for token in tokens:
        beat_durations.append(interpret_token(token))
    return beat_durations
