def count_digit_in_range(start: int, end: int, divisors: list, digit: int) -> int:
    """Counts the occurrences of a digit in numbers within a range divisible by any of the given divisors.

    Args:
        start: The starting number of the range (inclusive).
        end: The ending number of the range (inclusive).
        divisors: A list of integers representing the divisibility rules.
        digit: The digit to count (0-9).

    Returns:
        The number of times the specified digit appears in numbers within the range [start, end]
        that are divisible by any of the divisors.

    Raises:
        TypeError: if start, end, or any divisor is not an integer.
        ValueError: if digit is not an integer between 0 and 9.
    """

    # Input validation
    if not all(isinstance(d, int) for d in divisors):
        raise TypeError("Divisors must be integers.")
    if not isinstance(start, int) or not isinstance(end, int):
        raise TypeError("Start and end must be integers.")
    if not isinstance(digit, int):
        raise TypeError("Digit must be an integer.")
    if not 0 <= digit <= 9:
        raise ValueError("Digit must be between 0 and 9.")

    count = 0
    for num in range(start, end + 1):
        if any(num % divisor == 0 for divisor in divisors):
            count += str(num).count(str(digit))
    return count


def calculate_analysis(start: int, end: int, divisors: list, analysis_type: str, digit: int = None):
    """Calculates a specified analysis on numbers within a range divisible by given divisors.

    Args:
        start: The starting number of the range (inclusive).
        end: The ending number of the range (inclusive).
        divisors: A list of integers representing the divisibility rules.
        analysis_type: The type of analysis to perform ('count', 'sum', 'average', 'minimum', 'maximum').
        digit: The digit to count (only used if analysis_type is 'count').

    Returns:
        The result of the analysis.  Returns None if the analysis_type is invalid.

    Raises:
        TypeError: if start, end, or any divisor is not an integer.
        ValueError: if digit is not an integer between 0 and 9 (if applicable).
    """

    # Input validation (reusing from count_digit_in_range)
    if not all(isinstance(d, int) for d in divisors):
        raise TypeError("Divisors must be integers.")
    if not isinstance(start, int) or not isinstance(end, int):
        raise TypeError("Start and end must be integers.")
    if digit is not None and (not isinstance(digit, int) or not 0 <= digit <= 9):
        raise ValueError("Digit must be an integer between 0 and 9.")

    # Handle single divisor case
    if isinstance(divisors, int):
        divisors = [divisors]

    filtered_numbers = [num for num in range(start, end + 1) if any(num % divisor == 0 for divisor in divisors)]

    if not filtered_numbers:
        return 0  # Handle the case where no numbers meet the criteria

    if analysis_type == 'count':
        if digit is None:
            raise ValueError("Digit must be specified for 'count' analysis.")
        return count_digit_in_range(start, end, divisors, digit)
    elif analysis_type == 'sum':
        return sum(filtered_numbers)
    elif analysis_type == 'average':
        return sum(filtered_numbers) / len(filtered_numbers)
    elif analysis_type == 'minimum':
        return min(filtered_numbers)
    elif analysis_type == 'maximum':
        return max(filtered_numbers)
    else:
        raise ValueError("Invalid analysis type.")  # Raise ValueError for invalid analysis type



