import math

def is_simple_power(x, n):
    """
    Checks if x is a simple power of n (n**int = x).

    Args:
        x: The number to check.
        n: The base.

    Returns:
        True if x is a simple power of n, False otherwise.
    """

    if n == 0:
        return False
    if n == 1:
        return x == 1
    if x < 0 and n < 0:
        return False
    if x == 0:
        return n == 1

    if x <= 0 and n > 1:
        return False

    if n <= 0 and x > 0:
        return False

    try:
        power = math.log(x, n)
        return abs(power - round(power)) < 1e-10  # Account for potential floating-point errors
    except ValueError:
        return False  # Handle cases where log is undefined (e.g., x < 0, n <= 0)


def is_integer_power(x, n):
    """
    Checks if x is an integer power of n.  This is a more robust version
    that handles potential floating-point precision issues.

    Args:
        x: The number to check.
        n: The base.

    Returns:
        True if x is an integer power of n, False otherwise.
    """
    if n == 0:
        return False
    if n == 1:
        return x == 1
    if x < 0 and n < 0:
        return False
    if x == 0:
        return n == 1

    if x <= 0 and n > 1:
        return False

    if n <= 0 and x > 0:
        return False

    try:
        power = math.log(x, n)
        return power.is_integer()
    except ValueError:
        return False
