import unittest

def is_bored(S):
    """
    Counts the number of sentences in a string that start with the word "I".
    Sentences are delimited by '.', '?', or '!'.

    Args:
        S (str): The input string.

    Returns:
        int: The number of sentences starting with "I".
    """
    if not S:
        return 0

    sentences = []
    current_sentence = ""
    for char in S:
        current_sentence += char
        if char in ['.', '?', '!']:
            sentences.append(current_sentence.strip())
            current_sentence = ""

    if current_sentence:  # Handle the last sentence if it doesn't end with a delimiter
        sentences.append(current_sentence.strip())

    count = 0
    for sentence in sentences:
        if sentence.lower().startswith("i"):
            count += 1

    return count


class TestIsBored(unittest.TestCase):

    def test_empty_string(self):
        self.assertEqual(is_bored(""), 0)

    def test_no_boredom(self):
        self.assertEqual(is_bored("Hello world"), 0)

    def test_single_boredom(self):
        self.assertEqual(is_bored("The sky is blue. I love this weather"), 1)

    def test_multiple_boredom(self):
        self.assertEqual(is_bored("I am bored. I want to sleep. I need a vacation!"), 3)

    def test_mixed_sentences(self):
        self.assertEqual(is_bored("Hello. I am here? I am fine!"), 2)

    def test_case_insensitive(self):
        self.assertEqual(is_bored("i am here. I am fine!"), 2)

    def test_punctuation_after_i(self):
        self.assertEqual(is_bored("I, am here. I. am fine!"), 2)

    def test_no_delimiters(self):
        self.assertEqual(is_bored("I am here I am fine"), 2)

    def test_missing_delimiter(self):
        self.assertEqual(is_bored("I am here"), 1)

