def encode(message, vowel_map=None):
    """
    Encodes a message by swapping the case of each letter and replacing vowels.

    Args:
        message: The string to encode.
        vowel_map: A dictionary mapping vowels to their replacements.
                   If None, uses the default mapping.

    Returns:
        The encoded string.
    """
    if not isinstance(message, str):
        raise TypeError("Input must be a string.")

    if vowel_map is None:
        vowel_map = {
            'a': 'c', 'e': 'g', 'i': 'k', 'o': 'q', 'u': 'w',
            'A': 'C', 'E': 'G', 'I': 'K', 'O': 'Q', 'U': 'W'
        }

    encoded_message = ""
    for char in message:
        if 'a' <= char <= 'z':
            if char in vowel_map:
                encoded_message += vowel_map[char]
            else:
                encoded_message += char.upper()
        elif 'A' <= char <= 'Z':
            if char in vowel_map:
                encoded_message += vowel_map[char]
            else:
                encoded_message += char.lower()
        else:
            encoded_message += char

    return encoded_message
