app = FastAPI()

def get_closest_vowel(word: str) -> str:
    """
    Finds the closest vowel to a consonant pair from the right side of the word.
    """
    vowels = "aeiouAEIOU"
    consonants = "bcdfghjklmnpqrstvwxyzBCDFGHJKLMNPQRSTVWXYZ"

    if not word:
        return ""

    last_consonant_index = -1
    closest_vowel = ""
    min_distance = float('inf')

    for i in range(len(word) - 1, -1, -1):
        if word[i] in consonants:
            last_consonant_index = i
            break

    if last_consonant_index == -1:
        return ""

    for i in range(last_consonant_index - 1, -1, -1):
        if word[i] in vowels:
            distance = last_consonant_index - i
            if distance < min_distance:
                min_distance = distance
                closest_vowel = word[i]

    return closest_vowel


