def add_elements(arr, k):
    """
    Given a non-empty array of integers arr and an integer k, return
    the sum of the elements with at most two digits from the first k elements of arr.

    Example:

        Input: arr = [111,21,3,4000,5,6,7,8,9], k = 4
        Output: 24 # sum of 21 + 3

    Constraints:
        1. 1 <= len(arr) <= 100
        2. 1 <= k <= len(arr)
    """
    if not arr:
        return 0  # Handle empty array case (defensive programming)

    if k < 1 or k > len(arr):
        return 0  # Handle invalid k value (defensive programming)

    total_sum = 0
    for i in range(k):
        if abs(arr[i]) < 100:  # Check for at most two digits (using absolute value)
            total_sum += arr[i]

    return total_sum
