def digits(n):
    """Given a positive integer n, return the product of the odd digits.
    Return 0 if all digits are even.
    For example:
    digits(1)  == 1
    digits(4)  == 0
    digits(235) == 15
    """
    if not isinstance(n, int) or n < 0:
        return 0  # Handle non-positive integer input

    product = 1
    has_odd = False
    n_str = str(n)

    for digit in n_str:
        digit = int(digit)
        if digit % 2 != 0:
            product *= digit
            has_odd = True

    if not has_odd:
        return 0
    else:
        return product


