def factorial(n, memo={}):
    """Calculates the factorial of n using memoization."""
    if n in memo:
        return memo[n]
    if n == 0:
        return 1
    else:
        result = n * factorial(n-1, memo)
        memo[n] = result
        return result

def brazilian_factorial(n):
    """Calculates the Brazilian factorial of n."""
    result = 1
    for i in range(1, n + 1):
        result *= factorial(i)
    return result

